#!/usr/bin/env node
// Rewrite packages/contracts/src/ecb-currencies.ts from the ECB's list of euro reference rates, and print what
// changed (one line per currency, nothing when the table is current). Exits non-zero on a reply it can't trust, so
// a broken or partial reply never rewrites the table: one that lacks a currency the table lists counts as partial.
//
//   node .github/scripts/ecb-currencies.mjs [reply.csv]   (a saved reply instead of asking the ECB)
import {readFileSync, writeFileSync} from 'node:fs';

const TABLE = new URL('../../packages/contracts/src/ecb-currencies.ts', import.meta.url);
const SOURCE = 'https://data-api.ecb.europa.eu/service/data/EXR/D..EUR.SP00.A?lastNObservations=1&format=csvdata';
// The ECB skips weekends and TARGET holidays, at most five days in a row (Easter). A currency whose last rate is
// further behind the newest one has stopped.
const PUBLISHED_WITHIN_DAYS = 10;

const [header, ...rows] = parseCsv(process.argv[2] ? readFileSync(process.argv[2], 'utf8') : await fetchReply());
const column = (name) => {
	const index = header.indexOf(name);
	if (index < 0) throw new Error(`ECB reply has no ${name} column`);
	return index;
};
const currencyColumn = column('CURRENCY');
const dateColumn = column('TIME_PERIOD');
const rateColumn = column('OBS_VALUE');

const lastRates = new Map();
for (const row of rows) {
	const [currency, date, rate] = [row[currencyColumn], row[dateColumn], Number(row[rateColumn] || NaN)];
	if (
		row.length !== header.length ||
		!/^[A-Z]{3}$/.test(currency) ||
		!/^\d{4}-\d{2}-\d{2}$/.test(date) ||
		!(rate > 0 && Number.isFinite(rate))
	) {
		throw new Error(`ECB reply has an unexpected row: ${row.slice(0, 7).join(',')}`);
	}
	if (date > (lastRates.get(currency) ?? '')) lastRates.set(currency, date);
}
const newest = [...lastRates.values()].sort().at(-1);
if (lastRates.size < 20 || !newest) throw new Error(`ECB reply lists only ${lastRates.size} currencies`);
const cutoff = new Date(Date.parse(newest) - PUBLISHED_WITHIN_DAYS * 86_400_000).toISOString().slice(0, 10);

const table = new Map(
	[...lastRates].sort(([a], [b]) => (a < b ? -1 : 1)).map(([code, date]) => [code, date >= cutoff ? null : date]),
);
const previous = new Map(
	[...readFileSync(TABLE, 'utf8').matchAll(/^\t([A-Z]{3}): (null|'(\d{4}-\d{2}-\d{2})'),$/gm)].map((match) => [
		match[1],
		match[3] ?? null,
	]),
);

if (previous.size === 0) throw new Error('Could not read the current table');
// The ECB keeps the series of every currency it stopped, so one missing from the reply means the reply is incomplete.
const missing = [...previous.keys()].filter((code) => !table.has(code));
if (missing.length > 0) throw new Error(`ECB reply lacks ${missing.join(', ')}, which the table lists`);

for (const [code, last] of table) {
	if (!previous.has(code)) console.log(`${code}: new, ${last === null ? 'published' : `last rate ${last}`}`);
	else if (previous.get(code) !== last) {
		console.log(`${code}: ${last === null ? 'published again' : `last rate ${last}`} (was ${previous.get(code) ?? 'published'})`);
	}
}

writeFileSync(TABLE, render(table));

async function fetchReply() {
	const response = await fetch(SOURCE, {headers: {Accept: 'text/csv'}, signal: AbortSignal.timeout(60_000)});
	if (!response.ok) throw new Error(`ECB responded with HTTP ${response.status}`);
	return response.text();
}

function render(entries) {
	const lines = [...entries].map(([code, last]) => `\t${code}: ${last === null ? 'null' : `'${last}'`},`);
	return `/**
 * Every currency the ECB has published a daily euro reference rate for, with the date of its last rate, or null while
 * the ECB still publishes it. Tempo converts amounts only through these rates, so this is the one list of currencies
 * it can convert.
 *
 * Generated by \`.github/scripts/ecb-currencies.mjs\`; don't edit by hand. The ECB currencies workflow runs it monthly
 * and opens a pull request when the ECB adds, stops or resumes a currency.
 */
export const ECB_CURRENCIES: Readonly<Record<string, string | null>> = {
${lines.join('\n')}
};
`;
}

/** RFC 4180 CSV: quoted fields may hold commas, quotes ("") and line breaks. */
function parseCsv(text) {
	const records = [];
	let record = [];
	let field = '';
	let quoted = false;
	const endField = () => {
		record.push(field);
		field = '';
	};
	const endRecord = () => {
		endField();
		records.push(record);
		record = [];
	};
	for (let i = 0; i < text.length; i++) {
		const char = text[i];
		if (quoted) {
			if (char === '"' && text[i + 1] === '"') {
				field += '"';
				i++;
			} else if (char === '"') quoted = false;
			else field += char;
		} else if (char === '"') quoted = true;
		else if (char === ',') endField();
		else if (char === '\n' || char === '\r') {
			if (char === '\r' && text[i + 1] === '\n') i++;
			endRecord();
		} else field += char;
	}
	if (quoted) throw new Error('ECB reply ends inside a quoted field');
	if (field !== '' || record.length > 0) endRecord();
	return records.filter((row) => row.length > 1 || row[0] !== '');
}
